<script lang="ts">
 import SocialLogo from './SocialLogo.svelte';
 import ProfileImageCropper from './ProfileImageCropper.svelte';
 import {onMount,onDestroy} from 'svelte';
 import {guardUnsaved} from './unsaved';
 import {request} from './api';
 import {Input} from '$lib/components/ui/input';
 import {Textarea} from '$lib/components/ui/textarea';
 import {Button} from '$lib/components/ui/button';
 import * as Dialog from '$lib/components/ui/dialog';
 import * as DropdownMenu from '$lib/components/ui/dropdown-menu';
 import {LoaderCircle,Plus,Trash2,ExternalLink,ArrowUp,ArrowDown,Camera,MoreHorizontal,Pencil} from '@lucide/svelte';
 let {onSaved=()=>{}}:{onSaved?:(user:any)=>void}=$props();
 const socialPresets=[{label:'YouTube',url:'https://www.youtube.com/@'},{label:'Instagram',url:'https://www.instagram.com/'},{label:'TikTok',url:'https://www.tiktok.com/@'},{label:'LinkedIn',url:'https://www.linkedin.com/in/'},{label:'GitHub',url:'https://github.com/'},{label:'X',url:'https://x.com/'},{label:'Facebook',url:'https://www.facebook.com/'},{label:'Twitch',url:'https://www.twitch.tv/'},{label:'Discord',url:'https://discord.gg/'},{label:'Telegram',url:'https://t.me/'},{label:'Website',url:'https://'}];
 function moveSocial(index:number,direction:number){const target=index+direction;if(target<0||target>=profile.social_links.length)return;const links=[...profile.social_links];[links[index],links[target]]=[links[target],links[index]];profile.social_links=links;}
 const bannerPresets=[{id:'coastal-dawn',name:'Coastal dawn'},{id:'paper-studio',name:'Paper studio'},{id:'forest-light',name:'Forest light'},{id:'after-hours',name:'After hours'}];
 let bannerOpen=$state(false),socialOpen=$state(false),socialIndex=$state(-1),socialPlatform=$state('YouTube'),socialLabel=$state(''),socialURL=$state(''),socialError=$state('');
 let avatarInput=$state<HTMLInputElement>(),bannerInput=$state<HTMLInputElement>();
 function editSocial(index=-1){socialIndex=index;socialError='';const link=index>=0?profile.social_links[index]:null;socialPlatform=link?(socialPresets.some(p=>p.label===link.label)?link.label:'Custom'):'YouTube';socialLabel=link?.label||'';socialURL=link?.url||socialPresets[0].url;socialOpen=true;}
 function choosePlatform(){const preset=socialPresets.find(p=>p.label===socialPlatform);socialLabel=preset?.label||'';socialURL=preset?.url||'https://';}
 function saveSocial(){socialError='';const label=socialPlatform==='Custom'?socialLabel.trim():socialPlatform;let url:URL;try{url=new URL(socialURL.trim());if(url.protocol!=='https:'||url.username||url.password)throw new Error();}catch{socialError='Enter a complete HTTPS profile link.';return;}if(!label||label.length>40){socialError='Add a label of up to 40 characters.';return;}const domains:Record<string,string[]>={YouTube:['youtube.com','youtu.be'],Instagram:['instagram.com'],TikTok:['tiktok.com'],LinkedIn:['linkedin.com'],GitHub:['github.com'],X:['x.com','twitter.com'],Facebook:['facebook.com','fb.com'],Twitch:['twitch.tv'],Discord:['discord.com','discord.gg'],Telegram:['t.me','telegram.me']};const allowed=domains[label];if(allowed&&!allowed.some(domain=>url.hostname===domain||url.hostname.endsWith('.'+domain))){socialError=`Use a ${label} profile URL, or choose Other link.`;return;}const preset=socialPresets.find(item=>item.label===label);if(preset&&socialURL.trim()===preset.url){socialError='Complete the link with your profile address.';return;}const link={label,url:url.href};if(socialIndex>=0)profile.social_links=profile.social_links.map((item:any,i:number)=>i===socialIndex?link:item);else if(profile.social_links.length<8)profile.social_links=[...profile.social_links,link];socialOpen=false;}
 function linkHost(raw:string){try{return new URL(raw).hostname.replace(/^www\./,'');}catch{return raw;}}
 function selectBanner(id:string){profile.banner_url=`/banners/${id}.webp`;imagePreviews={...imagePreviews,banner:''};bannerOpen=false;notice='Banner selected. Save your profile to publish it.';}
 function removeBanner(){profile.banner_url='';imagePreviews={...imagePreviews,banner:''};bannerOpen=false;}

 let imagePreviews=$state<Record<string,string>>({});
 let crop=$state<{source:string;kind:'avatar'|'banner'}|null>(null);
 onDestroy(()=>closeCrop());
 function closeCrop(){if(crop)URL.revokeObjectURL(crop.source);crop=null;}
 function uploadImage(event:Event,kind:'avatar'|'banner'){
  const input=event.currentTarget as HTMLInputElement;const file=input.files?.[0];if(!file)return;error='';notice='';
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024){error='Choose a JPG, PNG or WebP image smaller than 12 MB.';input.value='';return;}
  bannerOpen=false;closeCrop();crop={source:URL.createObjectURL(file),kind};input.value='';
 }
 async function applyCrop(preview:string){if(!crop)return;const kind=crop.kind;busy=true;try{const result=await request('/profile/images',{kind,data:preview.split(',')[1]});profile[`${kind}_url`]=result.url;imagePreviews={...imagePreviews,[kind]:preview};notice='Image prepared. Save your profile to publish it.';closeCrop();}finally{busy=false;}}
 let savedProfile=$state('');
 guardUnsaved(()=>!!profile&&!!savedProfile&&JSON.stringify(profile)!==savedProfile,'Leave without saving profile changes?');
 let publicVideos=$state<any[]>([]);
 let profile=$state<any>(null),loading=$state(true),busy=$state(false),error=$state(''),notice=$state('');
 async function load(){loading=true;error='';try{const result=await request('/profile');profile={...result.channel,social_links:result.channel.social_links || []};savedProfile=JSON.stringify(profile);const channel=await request(`/channels/${encodeURIComponent(profile.handle)}`);publicVideos=channel.videos||[];}catch(e){error=(e as Error).message;}finally{loading=false;}}
 onMount(()=>{void load();});
 async function save(){busy=true;error='';notice='';try{const {name,bio,location,avatar_url,banner_url,website,social_links,featured_video_id}=profile;const result=await request('/profile',{name,bio,location,avatar_url,banner_url,website,social_links,featured_video_id},'PATCH');profile={...result.channel,social_links:result.channel.social_links || []};savedProfile=JSON.stringify(profile);onSaved(result.user);notice='Your public profile has been updated.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
{#if crop}<ProfileImageCropper source={crop.source} kind={crop.kind} onapply={applyCrop} oncancel={closeCrop}/>{/if}
<div class="page-heading"><h1>Edit public profile</h1><p>Your public identity for watching and creating. Email and security settings stay private.</p></div>
{#if error}<div class="cloud-alert" role="alert">{error}{#if !profile}<Button variant="outline" onclick={load}>Retry</Button>{/if}</div>{/if}{#if notice}<p class="cloud-notice" role="status">{notice}</p>{/if}
{#if loading}<div class="cloud-loading" role="status"><LoaderCircle class="size-5 animate-spin"/>Loading profile…</div>{:else if profile}
<input class="sr-only" type="file" aria-label="Choose avatar image" tabindex="-1" accept="image/jpeg,image/png,image/webp" bind:this={avatarInput} disabled={busy} onchange={e=>uploadImage(e,'avatar')}/>
<input class="sr-only" type="file" aria-label="Choose banner image" tabindex="-1" accept="image/jpeg,image/png,image/webp" bind:this={bannerInput} disabled={busy} onchange={e=>uploadImage(e,'banner')}/>
<form class="cloud-panel profile-editor" onsubmit={(event)=>{event.preventDefault();void save();}}>
<div class="profile-image-preview"><button type="button" class="banner-preview" disabled={busy} aria-label="Change channel banner" onclick={()=>bannerOpen=true}>{#if profile.banner_url}<img src={imagePreviews.banner||profile.banner_url} alt="Your channel banner" referrerpolicy="no-referrer"/>{/if}<span class="banner-edit"><Camera class="size-4"/>Edit banner</span></button><button type="button" class="avatar-preview" disabled={busy} aria-label="Change profile avatar" onclick={()=>avatarInput?.click()}>{#if profile.avatar_url}<img src={imagePreviews.avatar||profile.avatar_url} alt="Your avatar" referrerpolicy="no-referrer"/>{:else}<span>{(profile.name||'V').slice(0,1).toUpperCase()}</span>{/if}<span class="avatar-edit"><Camera class="size-3.5"/></span></button></div>
<div class="profile-identity-title"><h2>Public identity</h2><a href={`/channels/${profile.handle}`}>View profile<ExternalLink class="size-3.5"/></a></div>
<label for="profile-name">Display name</label><Input id="profile-name" bind:value={profile.name} required maxlength={100} autocomplete="name"/>
<label for="profile-bio">Bio</label><Textarea id="profile-bio" bind:value={profile.bio} rows={3} maxlength={2000} placeholder="Tell people a little about you."/>
<div class="form-grid"><div><label for="profile-location">Location <span class="subtle">(optional)</span></label><Input id="profile-location" bind:value={profile.location} maxlength={120}/></div><div><label for="profile-website">Website <span class="subtle">(optional)</span></label><Input id="profile-website" type="url" pattern="https://.*" bind:value={profile.website} placeholder="https://"/></div></div>
<div class="profile-links-heading"><div><h2>Social links</h2><p>Help people find you elsewhere.</p></div><Button type="button" variant="outline" size="sm" disabled={busy||profile.social_links.length>=8} onclick={()=>editSocial()}><Plus class="size-4"/>Add link</Button></div>
{#if profile.social_links.length}<div class="chosen-social-links">{#each profile.social_links as link,index}<div class="chosen-social-link"><SocialLogo name={link.label} size={18}/><button type="button" class="social-link-edit" onclick={()=>editSocial(index)}><strong>{link.label}</strong><span>{linkHost(link.url)}</span></button><DropdownMenu.Root><DropdownMenu.Trigger class="profile-link-menu" aria-label={`Options for ${link.label}`}><MoreHorizontal class="size-4"/></DropdownMenu.Trigger><DropdownMenu.Content align="end"><DropdownMenu.Item onSelect={()=>editSocial(index)}><Pencil class="size-4"/>Edit link</DropdownMenu.Item><DropdownMenu.Item disabled={index===0} onSelect={()=>moveSocial(index,-1)}><ArrowUp class="size-4"/>Move up</DropdownMenu.Item><DropdownMenu.Item disabled={index===profile.social_links.length-1} onSelect={()=>moveSocial(index,1)}><ArrowDown class="size-4"/>Move down</DropdownMenu.Item><DropdownMenu.Separator/><DropdownMenu.Item onSelect={()=>profile.social_links=profile.social_links.filter((_:unknown,i:number)=>i!==index)}><Trash2 class="size-4"/>Remove link</DropdownMenu.Item></DropdownMenu.Content></DropdownMenu.Root></div>{/each}</div>{:else}<p class="profile-quiet">No social links added.</p>{/if}
<details class="profile-advanced"><summary>More profile options</summary><label for="profile-featured">Featured video</label><select id="profile-featured" class="profile-featured-select" bind:value={profile.featured_video_id}><option value="">No featured video</option>{#each publicVideos as video}<option value={video.id}>{video.title}{video.audience==='members'?' · Premium':''}</option>{/each}</select><p class="field-help">Choose a published public video. Premium access rules still apply.</p><label for="profile-avatar-link">Avatar image link</label><Input id="profile-avatar-link" type="url" bind:value={profile.avatar_url} placeholder="https://" oninput={()=>imagePreviews={...imagePreviews,avatar:''}}/>{#if profile.avatar_url}<Button type="button" size="sm" variant="ghost" onclick={()=>{profile.avatar_url='';imagePreviews={...imagePreviews,avatar:''};}}>Remove avatar</Button>{/if}</details>
<div class="profile-save"><p class="field-help">Changes appear publicly after you save.</p><Button type="submit" disabled={busy}>{#if busy}<LoaderCircle class="size-4 animate-spin"/>{/if}Save profile</Button></div>
</form>
{/if}
<Dialog.Root bind:open={bannerOpen}><Dialog.Content class="sm:max-w-lg"><Dialog.Header><Dialog.Title>Channel banner</Dialog.Title><Dialog.Description>Upload your own image or choose a starting point.</Dialog.Description></Dialog.Header><Button variant="outline" disabled={busy} onclick={()=>bannerInput?.click()}><Camera class="size-4"/>Upload an image</Button><div class="banner-preset-grid">{#each bannerPresets as preset}<button type="button" class:selected={profile?.banner_url===`/banners/${preset.id}.webp`} onclick={()=>selectBanner(preset.id)} aria-label={`Use ${preset.name} banner`}><img src={`/banners/${preset.id}.webp`} alt="" loading="lazy"/><span>{preset.name}</span></button>{/each}</div><details class="banner-link-option"><summary>Use an image link</summary><label for="profile-banner-link" class="sr-only">HTTPS banner image link</label><Input id="profile-banner-link" type="url" value={profile?.banner_url?.startsWith('/banners/')?'':profile?.banner_url||''} placeholder="https://" oninput={e=>{profile.banner_url=e.currentTarget.value;imagePreviews={...imagePreviews,banner:''};}}/><p class="field-help">Use a secure HTTPS image link.</p></details><Dialog.Footer>{#if profile?.banner_url}<Button variant="ghost" onclick={removeBanner}>Remove banner</Button>{/if}<Button variant="outline" onclick={()=>bannerOpen=false}>Done</Button></Dialog.Footer></Dialog.Content></Dialog.Root>
<Dialog.Root bind:open={socialOpen}><Dialog.Content><Dialog.Header><Dialog.Title>{socialIndex>=0?'Edit social link':'Add social link'}</Dialog.Title><Dialog.Description>Choose a platform and add your profile URL.</Dialog.Description></Dialog.Header><form class="social-dialog-form" onsubmit={e=>{e.preventDefault();saveSocial();}}><label for="social-platform">Platform</label><select id="social-platform" bind:value={socialPlatform} onchange={choosePlatform}>{#each socialPresets as preset}<option value={preset.label}>{preset.label}</option>{/each}<option value="Custom">Other link</option></select>{#if socialPlatform==='Custom'}<label for="social-custom-label">Link label</label><Input id="social-custom-label" bind:value={socialLabel} required maxlength={40}/>{/if}<label for="social-profile-url">Profile URL</label><Input id="social-profile-url" type="url" pattern="https://.*" bind:value={socialURL} required placeholder="https://"/>{#if socialError}<p class="cloud-alert" role="alert">{socialError}</p>{/if}<Dialog.Footer><Button type="button" variant="outline" onclick={()=>socialOpen=false}>Cancel</Button><Button type="submit">{socialIndex>=0?'Update link':'Add link'}</Button></Dialog.Footer></form></Dialog.Content></Dialog.Root>
<style>
.profile-image-preview{position:relative;margin:0 0 42px}.banner-preview{height:170px;width:100%;background:var(--muted);border-radius:12px;overflow:hidden;display:block;position:relative;cursor:pointer}.banner-preview>img{width:100%;height:100%;object-fit:cover}.banner-edit{position:absolute;right:12px;bottom:12px;display:flex;align-items:center;gap:7px;padding:8px 10px;background:var(--background);color:var(--foreground);border-radius:var(--radius);font-size:12px}.avatar-preview{width:84px;height:84px;border:4px solid var(--background);border-radius:50%;background:var(--muted);position:absolute;left:20px;bottom:-28px;display:grid;place-items:center;font-size:27px;font-weight:600;cursor:pointer}.avatar-preview>img{width:100%;height:100%;border-radius:50%;object-fit:cover}.avatar-edit{position:absolute;right:-3px;bottom:-1px;background:var(--foreground);color:var(--background);border:2px solid var(--background);border-radius:50%;width:27px;height:27px;display:grid;place-items:center}.profile-identity-title,.profile-links-heading{display:flex;justify-content:space-between;align-items:center;gap:14px;margin:0 0 16px}.profile-identity-title h2,.profile-links-heading h2{font-size:15px;font-weight:600}.profile-identity-title a{font-size:12px;display:flex;gap:6px;align-items:center;color:var(--muted-foreground)}.profile-links-heading{margin-top:28px}.profile-links-heading p,.profile-quiet{font-size:12px;color:var(--muted-foreground);margin-top:6px;line-height:1.7}.chosen-social-links{display:grid;gap:0}.chosen-social-link{display:flex;align-items:center;gap:12px;padding:13px 0;border-bottom:1px solid var(--border)}.social-link-edit{flex:1;text-align:left;min-width:0;cursor:pointer}.social-link-edit strong{display:block;font-size:13px;font-weight:500}.social-link-edit span{display:block;font-size:11px;color:var(--muted-foreground);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:4px}:global(.profile-link-menu){display:grid;place-items:center;width:36px;height:36px;border-radius:var(--radius);cursor:pointer}:global(.profile-link-menu:hover){background:var(--accent)}.profile-advanced{margin:26px 0 0;border-top:1px solid var(--border);padding-top:18px}.profile-advanced summary,.banner-link-option summary{font-size:12px;color:var(--muted-foreground);cursor:pointer}.profile-advanced[open] summary,.banner-link-option[open] summary{margin-bottom:16px}.profile-advanced>label{display:block;font-size:12px;margin:16px 0 9px}.profile-featured-select,.social-dialog-form select{width:100%;min-height:36px;border:1px solid var(--border);border-radius:var(--radius);background:var(--background);color:var(--foreground);padding:6px 10px;font-size:13px}.social-dialog-form{display:grid;gap:10px}.social-dialog-form label{font-size:12px}.social-dialog-form :global([data-slot=dialog-footer]){margin-top:12px}.banner-preset-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.banner-preset-grid button{overflow:hidden;border:1px solid var(--border);border-radius:9px;text-align:left;cursor:pointer}.banner-preset-grid button:hover,.banner-preset-grid button.selected{border-color:var(--foreground)}.banner-preset-grid img{width:100%;aspect-ratio:3/1;object-fit:cover}.banner-preset-grid span{display:block;font-size:11px;padding:9px 10px}.banner-link-option{padding-block:5px}.banner-preview:focus-visible,.avatar-preview:focus-visible,.social-link-edit:focus-visible,.banner-preset-grid button:focus-visible,summary:focus-visible,select:focus-visible,:global(.profile-link-menu:focus-visible){outline:2px solid var(--ring);outline-offset:3px}.profile-save{margin-top:28px;padding-top:20px;border-top:1px solid var(--border)}@media(max-width:600px){.banner-preview{height:130px}.avatar-preview{width:76px;height:76px;left:14px}.profile-image-preview{margin-bottom:40px}.banner-edit{font-size:11px;padding:7px 9px}}
</style>
